import sys, os, json, hashlib, subprocess, tarfile, io, difflib, re
from pathlib import Path
sys.path.insert(0, '/home/name/.hermes/cache/scratch')
from edit_delete_runner import run, root
scratch=Path('/home/name/.hermes/cache/scratch/edit-delete-line-integration')
allow=json.loads((scratch/'allowlist.json').read_text())
head='2c6f01ce87fe6d8f9f8b1bd6f38a717d7ed5233d'
mode=sys.argv[1]

def sha(data):
    return hashlib.sha256(data).hexdigest()

def gitbytes(path):
    p=subprocess.run(['git','show',head+':'+path],cwd=root,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    return p.stdout if p.returncode == 0 else None

def lf_lines(data):
    parts=data.split(b'\n')
    return [p+b'\n' for p in parts[:-1]]+([parts[-1]] if parts[-1] else [])

if mode == 'preserve':
    dirty=subprocess.check_output(['git','diff','--name-only','-z'],cwd=root).split(b'\0')
    fixed={os.fsdecode(p): (sha((root/os.fsdecode(p)).read_bytes()) if (root/os.fsdecode(p)).exists() else None) for p in dirty if p and os.fsdecode(p) not in allow and os.fsdecode(p) != 'docs/sessions.txt'}
    (scratch/'unrelated-before.json').write_text(json.dumps(fixed,indent=2)+'\n')
    print('fixed unrelated tracked dirty paths',len(fixed))
elif mode == 'patch':
    candidates={}
    edits=json.loads((scratch/'docs-edits.json').read_text())
    for p in allow:
        b=gitbytes(p)
        if p in edits:
            text=b.decode()
            for old,new in edits[p]:
                assert text.count(old) == 1,(p,old)
                text=text.replace(old,new)
            a=text.encode()
            (scratch/(p+'.candidate')).write_bytes(a)
        else:
            a=(root/p).read_bytes()
        candidates[p]=a
    patch=b''
    for p,a in candidates.items():
        b=gitbytes(p)
        patch+=b''.join(difflib.diff_bytes(difflib.unified_diff,lf_lines(b or b''),lf_lines(a),fromfile=('a/'+p).encode() if b is not None else b'/dev/null',tofile=('b/'+p).encode()))
    (scratch/'integration.patch').write_bytes(patch)
    manifest={'head':head,'allowlist':allow,'patch_sha256':sha(patch),'candidates':{p:sha(a) for p,a in candidates.items()}}
    anchors=['src/main.c','src/shell.c','src/shell.h','src/registry.h','src/cmd_lines.c','src/cmd_lines.h','src/cmd_spec.h','src/cmd_edit_replace_line.c','src/cmd_edit_replace_line.h','src/cmd_edit_insert_line.c','src/cmd_edit_insert_line.h','src/traverse.c','src/traverse.h','tests/test_help.c','tests/test_output.h','tests/test_recursive.c']
    manifest['anchors']={p:sha((root/p).read_bytes()) for p in anchors}
    for p in anchors:
        assert (root/p).read_bytes() == gitbytes(p),p
    deps=[root/'build/argtable3/lib/libargtable3.a',root/'build/argtable3/include/argtable3.h',root/'build/cunit/lib/libcunit.a',root/'build/cunit/include/CUnit/CUnit.h']
    manifest['dependencies']={str(p):sha(p.read_bytes()) for p in deps}
    (scratch/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print('explicit candidate paths',len(allow),'patch sha256',manifest['patch_sha256'])
elif mode == 'fresh':
    name=sys.argv[2]
    checkout=scratch/name
    assert not checkout.exists(),checkout
    checkout.mkdir()
    archive=subprocess.check_output(['git','archive',head],cwd=root)
    with tarfile.open(fileobj=io.BytesIO(archive)) as t:
        t.extractall(checkout,filter='fully_trusted')
    run(name+'-patch-check',['git','apply','--check',str(scratch/'integration.patch')],cwd=checkout)
    run(name+'-source-doc-whitespace',['git','apply','--check',
        '--whitespace=error-all',
        '--exclude=logs/commands/edit-delete-line-execution.log',
        str(scratch/'integration.patch')],cwd=checkout)
    run(name+'-patch-apply',['git','apply',str(scratch/'integration.patch')],cwd=checkout)
    manifest=json.loads((scratch/'manifest.json').read_text())
    for group in ['candidates','anchors']:
        for p,h in manifest[group].items():
            assert sha((checkout/p).read_bytes()) == h,(group,p)
    # Only installed third-party dependency trees are shared.
    (checkout/'build').mkdir(exist_ok=True)
    for d in ['argtable3','cunit']:
        (checkout/'build'/d).symlink_to(root/'build'/d,target_is_directory=True)
    print(name,'exact candidate and unchanged anchor blobs verified',checkout)
elif mode == 'audit':
    fixed=json.loads((scratch/'unrelated-before.json').read_text())
    for p,h in fixed.items():
        current=sha((root/p).read_bytes()) if (root/p).exists() else None
        assert current == h, p
    assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=root).decode().strip() == head
    assert subprocess.check_output(['git','diff','--cached','--name-only'],cwd=root) == b''
    manifest=json.loads((scratch/'manifest.json').read_text())
    for p,h in manifest['candidates'].items():
        candidate=(scratch/(p+'.candidate')) if p in ['README.md','FILES.md'] else root/p
        assert sha(candidate.read_bytes()) == h,p
    for name in sys.argv[2:]:
        checkout=scratch/name
        for group in ['candidates','anchors']:
            for p,h in manifest[group].items():
                assert sha((checkout/p).read_bytes()) == h,(name,group,p)
    print('HEAD/index unchanged; all fixed unrelated tracked paths preserved; final hashes match')
